-- Independent contextual power, authority and directed comparative asymmetry.
BEGIN;
ALTER TABLE niccolo.actor_epistemic_state_events DROP CONSTRAINT actor_epistemic_state_events_dimension_check;
ALTER TABLE niccolo.actor_epistemic_state_events ADD CONSTRAINT actor_epistemic_state_events_dimension_check CHECK (dimension IN (
 'EXPOSURE','ACCESS','PERCEPTION','ATTENTION','EXAMINATION','COMPREHENSION','RECALL','SUSPICION','INCLINATION','DOUBT','BELIEF','SUSPENDED_JUDGMENT','CLAIMED_KNOWLEDGE','PERCEIVED_KNOWLEDGE','EVIDENCE_SUPPORTED_KNOWLEDGE',
 'INTEREST','CURIOSITY','INDIFFERENCE','AVERSION','LIMITED_INQUIRY','DENIABILITY_PRESERVATION','DELEGATED_KNOWING','DOCUMENTATION_AVOIDANCE',
 'TRUST_COMPETENCE','TRUST_CONFIDENTIALITY','TRUST_TRUTHFULNESS','LOYALTY','EGO_PROTECTION','IDENTITY_PROTECTION',
 'AUTONOMY_DECIDE','AUTONOMY_REFUSE','AUTONOMY_DISAGREE','AUTONOMY_EXIT','AUTONOMY_SEEK_REVIEW','AUTONOMY_ACQUIRE_INFORMATION','AUTONOMY_REVISE_COMMITMENTS',
 'INCENTIVE','PRESSURE','COMMUNICATED_THREAT','ADVERSE_CONDITION','COERCION','CONSTRAINT','DEPENDENCY','LEVERAGE',
 'THREAT_CAPABILITY','THREAT_INTENT','THREAT_PERCEIVED_CREDIBILITY','THREAT_OUTCOME','VULNERABILITY','COERCION_SUSCEPTIBILITY','COMPLIANCE','CONSENT','SUBMISSION',
 'INFLUENCE_CAPACITY','INFLUENCE_ACT','INFLUENCE_INTENDED_EFFECT','INFLUENCE_ACTUAL_EFFECT','INFLUENCE_PERCEIVED_SUCCESS','EPISTEMIC_POWER','FORMAL_AUTHORITY','ASYMMETRY_INFORMATION','ASYMMETRY_ACCESS','ASYMMETRY_UNDERSTANDING','ASYMMETRY_META_KNOWLEDGE','ASYMMETRY_INFLUENCE'));
ALTER TABLE niccolo.actor_epistemic_state_events DROP CONSTRAINT actor_epistemic_counterparty_qualification;
ALTER TABLE niccolo.actor_epistemic_state_events ADD CONSTRAINT actor_epistemic_counterparty_qualification CHECK (
 (counterparty_actor_id IS NULL OR (counterparty_actor_id<>subject_actor_id AND dimension IN ('INCENTIVE','PRESSURE','COMMUNICATED_THREAT','ADVERSE_CONDITION','COERCION','CONSTRAINT','DEPENDENCY','LEVERAGE','THREAT_CAPABILITY','THREAT_INTENT','THREAT_PERCEIVED_CREDIBILITY','THREAT_OUTCOME','VULNERABILITY','COERCION_SUSCEPTIBILITY','COMPLIANCE','CONSENT','SUBMISSION','INFLUENCE_CAPACITY','INFLUENCE_ACT','INFLUENCE_INTENDED_EFFECT','INFLUENCE_ACTUAL_EFFECT','INFLUENCE_PERCEIVED_SUCCESS','EPISTEMIC_POWER','FORMAL_AUTHORITY','ASYMMETRY_INFORMATION','ASYMMETRY_ACCESS','ASYMMETRY_UNDERSTANDING','ASYMMETRY_META_KNOWLEDGE','ASYMMETRY_INFLUENCE')))
 AND (dimension NOT IN ('THREAT_CAPABILITY','THREAT_INTENT','INFLUENCE_CAPACITY','INFLUENCE_ACT','INFLUENCE_INTENDED_EFFECT','ASYMMETRY_INFORMATION','ASYMMETRY_ACCESS','ASYMMETRY_UNDERSTANDING','ASYMMETRY_META_KNOWLEDGE','ASYMMETRY_INFLUENCE') OR counterparty_actor_id IS NOT NULL));
ALTER TABLE niccolo.actor_epistemic_state_events ADD CONSTRAINT actor_epistemic_power_object CHECK (dimension NOT IN ('EPISTEMIC_POWER','FORMAL_AUTHORITY','ASYMMETRY_INFORMATION','ASYMMETRY_ACCESS','ASYMMETRY_UNDERSTANDING','ASYMMETRY_META_KNOWLEDGE','ASYMMETRY_INFLUENCE') OR target_object_id IS NOT NULL);
COMMIT;
